// 📁 src/utils/api.js
import axios from "axios";
import toast from "react-hot-toast";

// Détection environnement local ou prod
const api = axios.create({
  baseURL: import.meta.env.PROD
    ? "https://cdotchad.com/api"
    : "http://localhost:5000/api",
  withCredentials: true,
});

// ✅ Ajouter cette fonction si manquante :
export const fetchServices = async () => {
  const response = await api.get("/services");
  return response.data;
};

// 🔐 Intercepteur de requêtes : ajoute automatiquement le token admin
api.interceptors.request.use((config) => {
  const token = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

// ❌ Gestion des erreurs globales (optionnelle)
api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (
      error.response &&
      error.response.status === 401 &&
      error.response.data?.message === "Token d'authentification manquant"
    ) {
      toast.error("⛔ Authentification requise. Veuillez vous reconnecter.");
    } else if (
      error.response &&
      error.response.status === 403 &&
      error.response.data?.message === "Token invalide ou expiré"
    ) {
      toast.error("⛔ Session expirée. Veuillez vous reconnecter.");
    }
    return Promise.reject(error);
  }
);

export default api;
